import {PRESETS,recipe} from './surface.js';
import {hullMaterial,metricUV} from './material.js';
import {ObjectViewer} from '../viewer/object-viewer.js';
import {blueprint} from '../ships/blueprint.js';
import {shipModel} from '../ships/model.js';
import * as T from 'three/webgpu';
const $=id=>document.getElementById(id),status=text=>{$('hullStatus').textContent=text;};
let state=recipe(),images={},bitmaps={},viewer,maps,levels,worker,request=0,timer,initPromise,frameDistance=3,active=false,busy=false;
const ranges=[['paintCoverage','Paint coverage',0,1,.01],['roughness','Surface roughness',.18,.98,.01],['wear','Wear amount',0,1,.01],['panels','Panels per tile',2,12,1],['seam','Seam width / metres',.001,.025,.001],['tileMeters','Tile span / metres',.5,8,.1],['grain','Microdetail strength',0,1,.01],['heat','Thermal exposure',0,1,.01],['bitmapMix','Bitmap layer blend',0,1,.01]];
for(const [key,label,min,max,step]of ranges){const el=document.createElement('label');el.textContent=label;const out=document.createElement('output'),input=document.createElement('input');input.type='range';Object.assign(input,{min,max,step});input.dataset.key=key;el.append(out,input);input.oninput=()=>{state[key]=Number(input.value);out.value=input.value;schedule();};$('hullSliders').append(el);}
for(const [id,preset]of Object.entries(PRESETS)){const b=document.createElement('button');b.textContent=preset.name;b.onclick=()=>{state=recipe({preset:id,seed:state.seed});sync();schedule();};$('hullPresetCards').append(b);}
for(const channel of ['color','normal','roughness','metallic','ao','height','mask']){const row=document.createElement('div');row.className='bitmapRow';const label=document.createElement('label');label.textContent=channel;const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';const clear=document.createElement('button');clear.textContent='Remove';clear.onclick=()=>{delete images[channel];delete bitmaps[channel];input.value='';schedule();};input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>12*1024*1024)throw Error('Choose an image smaller than 12 MB.');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});bitmaps[channel]=await decode(url);images[channel]=await encodeBitmap(bitmaps[channel]);state.bitmapMix=1;sync();schedule();}catch(e){status(e.message);}};label.append(input);row.append(label,clear);$('hullBitmapInputs').append(row);}
async function decode(url){if(typeof url!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(url)||url.length>18e6)throw Error('Invalid embedded bitmap.');const blob=await(await fetch(url)).blob(),image=await createImageBitmap(blob);if(image.width*image.height>67108864){image.close();throw Error('Bitmap exceeds 64 megapixels.');}const factor=Math.min(1,1024/image.width,1024/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*factor));canvas.height=Math.max(1,Math.round(image.height*factor));const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();return{width:canvas.width,height:canvas.height,data:ctx.getImageData(0,0,canvas.width,canvas.height).data};}
function encodeBitmap(b){const c=document.createElement('canvas');c.width=b.width;c.height=b.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(b.data),b.width,b.height),0,0);return c.toDataURL('image/png');}
function sync(){for(const [key]of ranges){const el=document.querySelector(`[data-key="${key}"]`);el.value=state[key];el.previousElementSibling.value=String(state[key]);}$('hullSeed').value=state.seed;$('hullPaint').value=state.paint;$('hullSubstrate').value=state.substrate;$('hullEnvironment').value=state.environment;$('hullMarkings').checked=state.markings;$('hullTitle').textContent=PRESETS[state.preset].name;}
function schedule(){clearTimeout(timer);timer=setTimeout(bake,120);}
function bake(){if(!worker)return;if(busy){worker.terminate();startWorker();}busy=true;const id=++request;status('Baking material layers…');worker.postMessage({id,recipe:state,bitmaps,size:Number($('hullResolution').value)});}
function thumbnail(){if(!maps)return;const canvas=$('hullMapThumb'),channel=$('hullChannel').value,source=channel==='normal'?maps.normal:channel==='color'||channel==='pbr'?maps.color:['paint','wear','seams','heat'].includes(channel)?maps.masks:maps.surface;const data=new Uint8ClampedArray(source),component={ao:0,roughness:1,metallic:2,height:3,paint:0,wear:1,seams:2,heat:3}[channel];if(component!==undefined)for(let i=0;i<data.length;i+=4){data[i]=data[i+1]=data[i+2]=source[i+component];data[i+3]=255;}const raw=document.createElement('canvas');raw.width=raw.height=maps.size;raw.getContext('2d').putImageData(new ImageData(data,maps.size,maps.size),0,0);canvas.width=canvas.height=maps.size;canvas.getContext('2d').drawImage(raw,0,0);}
function rebuild(preserve=false){if(!viewer||!maps)return;const oldPosition=viewer.camera.position.clone(),oldTarget=viewer.controls.target.clone(),mat=hullMaterial(maps,levels,{channel:$('hullChannel').value}),shape=$('hullShape').value;let object;
 if(shape==='ship'||shape==='module'){const plan=blueprint(state.seed);object=shipModel(plan,{hull:mat,single:shape==='module'?'habitat':null});if(!object.children.length){viewer.disposeObject(object);mat.dispose();object=new T.Mesh(metricUV(new T.CylinderGeometry(1,1,2,64),state.tileMeters),hullMaterial(maps,levels,{channel:$('hullChannel').value}));}}
 else{const geometry=shape==='plate'?new T.BoxGeometry(2,2,.08):new T.CylinderGeometry(1,1,3,96);object=new T.Mesh(metricUV(geometry,state.tileMeters),mat);if(shape==='cylinder')object.rotation.z=Math.PI/2;}

 viewer.setObject(object,{disposePrevious:true});frameDistance=viewer.camera.position.distanceTo(viewer.controls.target);if(preserve){viewer.camera.position.copy(oldPosition);viewer.controls.target.copy(oldTarget);viewer.controls.update();}else $('hullDistance').value=1;thumbnail();light();}
function light(){if(!viewer)return;const mode=$('hullLighting').value,a=Number($('hullLight').value)*Math.PI/180;viewer.key.position.set(Math.sin(a)*6,mode==='grazing'?.2:4,Math.cos(a)*6);viewer.key.intensity=mode==='space'?3.2:2.8;viewer.rim.intensity=mode==='studio'?.6:.1;viewer.fill.intensity=mode==='studio'?.6:.04;viewer.scene.environmentIntensity=mode==='studio'?.65:.08;viewer.renderer.toneMappingExposure=Number($('hullExposure').value);}
async function initialize(){viewer=await new ObjectViewer().initialize($('hullViewport'));viewer.bloom.strength.value=0;viewer.paused=!active;viewer.onError=status;startWorker();bake();}
function startWorker(){worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.id!==request)return;busy=false;if(data.error){status('Bake failed: '+data.error);return;}const preserve=Boolean(maps);maps=data.maps;levels=data.levels;rebuild(preserve);status(`${maps.size}² · ${levels.length} filtered mip levels · ${Object.keys(bitmaps).length} bitmap layers · seed ${maps.recipe.seed}`);};worker.onerror=e=>{busy=false;status('Material worker failed: '+e.message);};}
for(const button of document.querySelectorAll('[data-category]'))button.addEventListener('click',()=>{active=button.dataset.category==='spacecraft';document.body.classList.toggle('hullMode',active);$('hullLab').hidden=!active;if(viewer)viewer.paused=!active;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.dispatchEvent(new CustomEvent('material-category',{detail:button.dataset.category}));if(active&&!initPromise)initPromise=initialize().catch(e=>{status('WebGPU preview unavailable: '+e.message);});});
for(const [id,key]of [['hullSeed','seed'],['hullPaint','paint'],['hullSubstrate','substrate'],['hullEnvironment','environment']])$(id).oninput=()=>{state[key]=$(id).value;schedule();};$('hullMarkings').onchange=()=>{state.markings=$('hullMarkings').checked;schedule();};$('hullResolution').onchange=schedule;$('hullShape').onchange=()=>rebuild();$('hullChannel').onchange=()=>rebuild(true);$('hullLighting').onchange=light;for(const id of ['hullLight','hullExposure'])$(id).oninput=light;
$('hullDistance').oninput=()=>{if(!viewer)return;const direction=viewer.camera.position.clone().sub(viewer.controls.target).normalize();viewer.camera.position.copy(viewer.controls.target).addScaledVector(direction,frameDistance*Number($('hullDistance').value));viewer.controls.update();};$('hullFrame').onclick=()=>{viewer?.frame();if(viewer)frameDistance=viewer.camera.position.distanceTo(viewer.controls.target);$('hullDistance').value=1;};$('hullRotate').onclick=()=>{if(!viewer)return;viewer.controls.autoRotate=!viewer.controls.autoRotate;$('hullRotate').setAttribute('aria-pressed',String(viewer.controls.autoRotate));};$('hullClearBitmaps').onclick=()=>{images={};bitmaps={};document.querySelectorAll('#hullBitmapInputs input').forEach(i=>i.value='');schedule();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const bundle=()=>({schema:'aether-hull-material',version:1,recipe:recipe(state),images});
async function load(data){if(data.schema!=='aether-hull-material'||data.version!==1)throw Error('Choose an Aether hull material recipe, version 1.');const nextImages=data.images??{},next={};for(const [key,url]of Object.entries(nextImages)){if(!['color','normal','roughness','metallic','ao','height','mask'].includes(key))throw Error('Unknown bitmap channel');next[key]=await decode(url);}state=recipe(data.recipe);images=nextImages;bitmaps=next;sync();schedule();}
// IndexedDB preserves embedded bitmaps without localStorage's small quota.
async function database(){return new Promise((resolve,reject)=>{const req=indexedDB.open('aether-hull-materials',1);req.onupgradeneeded=()=>req.result.createObjectStore('recipes');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function saved(write=false){const db=await database();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('recipes',write?'readwrite':'readonly'),req=write?tx.objectStore('recipes').put(bundle(),'current'):tx.objectStore('recipes').get('current');let result;req.onsuccess=()=>{result=req.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{db.close();}}
$('hullSave').onclick=async()=>{try{await saved(true);status('Material and bitmap layers saved on this device.');}catch(e){status('Could not save: '+e.message);}};$('hullLoad').onclick=async()=>{try{const data=await saved();if(!data)throw Error('No saved hull material yet.');await load(data);}catch(e){status(e.message);}};$('hullExport').onclick=()=>download(new Blob([JSON.stringify(bundle())],{type:'application/json'}),'aether-hull-material.json');$('hullImport').onclick=()=>$('hullRecipeFile').click();$('hullRecipeFile').onchange=async()=>{try{const f=$('hullRecipeFile').files[0];if(!f)return;if(f.size>64e6)throw Error('Recipe exceeds 64 MB.');await load(JSON.parse(await f.text()));}catch(e){status('Import failed: '+e.message);}finally{$('hullRecipeFile').value='';}};
$('hullExportMap').onclick=()=>{if(!maps)return;thumbnail();$('hullMapThumb').toBlob(blob=>{if(blob)download(blob,`aether-${$('hullChannel').value==='pbr'?'color':$('hullChannel').value}.png`);});};
$('hullApply').onclick=async()=>{try{const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('recipes','readwrite');tx.objectStore('recipes').put(bundle(),'ship');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();status('Applied. Open Spaceship Studio and select Custom material.');}catch(e){status('Could not apply: '+e.message);}};
window.addEventListener('pagehide',()=>{worker?.terminate();viewer?.dispose();});sync();
